// Quarterly Reports API
export const quarterlyApi = {
  async getQuarterlyReports() {
    try {
      const response = await fetch(`${API_BASE_URL}/quarterly`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      return await response.json();
    } catch (error) {
      console.error('Error fetching quarterly reports:', error);
      throw error;
    }
  },

  async getQuarterlyReportById(id) {
    try {
      const response = await fetch(`${API_BASE_URL}/quarterly/${id}`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      return await response.json();
    } catch (error) {
      console.error(`Error fetching quarterly report ${id}:`, error);
      throw error;
    }
  },

  async generateQuarterlyReport(year, quarter) {
    try {
      const response = await fetch(`${API_BASE_URL}/quarterly/generate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ year, quarter }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Unknown error');
      }

      return await response.json();
    } catch (error) {
      console.error('Error generating quarterly report:', error);
      throw error;
    }
  }
};
